import numpy as np, collections
def parse(g):
    g=np.array(g)
    H,W=g.shape
    # bands: rows belonging to 3-row tile groups; find via nonzero runs of height>=3
    band_rows=[]; cur=None
    for r in range(H):
        if any(g[r]!=0):
            if cur is None: cur=[r,r+2]
            elif r!=cur[1]+1: band_rows.append(cur); cur=[r,r+2]
        else:
            if cur is not None: band_rows.append(cur); cur=None
    if cur is not None: band_rows.append(cur)
    # tile cols: for each band, nonzero cols
    tiles=[]
    for br,(a,b) in enumerate(band_rows):
        nz=[c for c in range(W) if any(g[r][c]!=0 for r in range(a,a+3))]
        comp=collections.defaultdict(list)
        for c in nz:
            vals=[g[r][c] for r in range(a,a+3)]
            if vals.count(vals[0])==3 or vals[0]==vals[1]==vals[2]:
